from pathlib import Path
import streamlit as st
import torch
from transformers import AutoModelForCausalLM, AutoTokenizer

LOCAL_MODEL_DIR = Path("lab_outputs/study_tip_gpt2")
HF_MODEL_ID = "YASH7080192/study-tip-gpt2"

st.set_page_config(page_title="Study Tip Generator", page_icon="📚", layout="centered")

st.title("Study Tip Generator")
st.caption("AI-generated study tips powered by fine-tuned GPT-2 (for instructor review).")

st.info(
    "**Disclosure:** Tips are generated by a small fine-tuned language model (GPT-2). "
    "Always verify technical accuracy with your instructor or course textbook before studying."
)


@st.cache_resource(show_spinner="Loading fine-tuned GPT-2 model...")
def load_model():
    source = str(LOCAL_MODEL_DIR) if LOCAL_MODEL_DIR.exists() else HF_MODEL_ID
    tokenizer = AutoTokenizer.from_pretrained(source)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    model = AutoModelForCausalLM.from_pretrained(source)
    model.eval()
    return tokenizer, model


topic = st.text_input("Enter a study topic", placeholder="e.g., recursion, binary search, Bayes theorem")

if st.button("Generate", type="primary"):
    cleaned = topic.strip()
    if not cleaned:
        st.warning("Enter a study topic first.")
    else:
        tokenizer, model = load_model()
        prompt = f"Topic: {cleaned}\nStudy tip:"
        inputs = tokenizer(prompt, return_tensors="pt")
        with torch.no_grad():
            output_ids = model.generate(
                **inputs,
                max_new_tokens=45,
                do_sample=False,
                pad_token_id=tokenizer.eos_token_id,
            )
        generated_tokens = output_ids[0][inputs["input_ids"].shape[1]:]
        tip = tokenizer.decode(generated_tokens, skip_special_tokens=True).strip()

        st.subheader("Generated Study Tip")
        st.success(tip if tip else "No tip generated. Try another topic.")